  1  /**
  2   * Shared API request helper for the documented /api/v1 envelope.
  3   * Each call supplies its own workspaceId + accessToken; credentials are
  4   * never stored in module state.
  5   */
  6  export class ApiError extends Error {
  7    code: string;
  8    status: number;
  9  
 10    constructor(code: string, message: string, status: number) {
 11      super(message);
 12      this.name = "ApiError";
 13      this.code = code;
 14      this.status = status;
 15    }
 16  }
 17  
 18  export const apiBaseUrl = (process.env.NEXT_PUBLIC_API_BASE_URL?.trim() ?? "").replace(/\/$/, "");
 19  
 20  export function isRecord(value: unknown): value is Record<string, unknown> {
 21    return typeof value === "object" && value !== null;
 22  }
 23  
 24  /**
 25   * Registered by the session provider. When a request comes back 401 the
 26   * transport asks it for a renewed access token (single-flight behind the
 27   * provider's own refresh scheduling) and replays the request exactly once
 28   * with it; ``null`` means the session is really gone and the original 401
 29   * stands. Auth endpoints themselves never carry a token and never trigger it,
 30   * so there is no refresh loop.
 31   */
 32  type TokenRefresher = () => Promise<string | null>;
 33  let tokenRefresher: TokenRefresher | null = null;
 34  
 35  export function setTokenRefresher(refresher: TokenRefresher | null): void {
 36    tokenRefresher = refresher;
 37  }
