 39  /**
 40   * Core transport for the documented /api/v1 envelope.
 41   *
 42   * `credentials: "include"` is always sent so the backend-owned HttpOnly
 43   * refresh cookie travels with /auth/* calls. The refresh cookie is never
 44   * read by JavaScript.
 45   */
 46  async function transport<T>(
 47    path: string,
 48    init: { method?: string; body?: unknown; accessToken?: string; formData?: FormData; signal?: AbortSignal },
 49  ): Promise<T> {
 50    const send = (token: string | undefined) => {
 51      const hasJsonBody = init.formData === undefined && init.body !== undefined;
 52      return fetch(`${apiBaseUrl}${path}`, {
 53        method: init.method ?? "GET",
 54        headers: {
 55          ...(hasJsonBody ? { "Content-Type": "application/json" } : {}),
 56          ...(token ? { Authorization: `Bearer ${token}` } : {}),
 57        },
 58        credentials: "include",
 59        ...(init.signal !== undefined ? { signal: init.signal } : {}),
 60        ...(init.formData !== undefined
 61          ? { body: init.formData }
 62          : hasJsonBody
 63            ? { body: JSON.stringify(init.body) }
 64            : {}),
 65      });
 66    };
 67    const token = init.accessToken?.trim();
 68    let response = await send(token);
 69    if (response.status === 401 && token && tokenRefresher) {
 70      const renewed = await tokenRefresher().catch(() => null);
 71      // A renewal that returned the unchanged token (no rotation upstream) is
 72      // treated as "no renewal": replaying with it would just 401 again. The
 73      // caller keeps the original 401 even though the session is technically
 74      // healthy -- a rare, fail-visible outcome beats a retry storm.
 75      if (renewed && renewed.trim() && renewed.trim() !== token) {
 76        response = await send(renewed.trim());
 77      }
 78    }
 79    const body = (await response.json().catch(() => null)) as unknown;
 80    if (!response.ok) {
 81      const error = isRecord(body) && isRecord(body.error) ? body.error : {};
 82      // A body that is not the API envelope (a proxy's HTML error page, an
 83      // empty body) means the API itself never answered -- report that as its
 84      // own condition instead of a generic request failure.
 85      const envelopeMissing = !isRecord(body) || !isRecord(body.error);
 86      const code = envelopeMissing
 87        ? "UPSTREAM_UNAVAILABLE"
 88        : typeof error.code === "string"
 89          ? error.code
 90          : "REQUEST_FAILED";
 91      throw new ApiError(
 92        code,
 93        typeof error.message === "string" ? error.message : "The API request failed.",
 94        response.status,
 95      );
 96    }
 97    return body as T;
 98  }
