100  export async function apiRequest<T>(
101    path: string,
102    accessToken: string,
103    init?: { method?: string; body?: unknown; signal?: AbortSignal },
104  ): Promise<T> {
105    const token = accessToken.trim();
106    if (!token) {
107      throw new ApiError("SESSION_REQUIRED", "A workspace session with an access token is required.", 401);
108    }
109    return transport<T>(path, {
110      method: init?.method,
111      body: init?.body,
112      signal: init?.signal,
113      accessToken: token,
114    });
115  }
