117  /** Multipart upload against the same envelope and error contract. */
118  export async function apiUpload<T>(
119    path: string,
120    accessToken: string,
121    formData: FormData,
122    init?: { signal?: AbortSignal },
123  ): Promise<T> {
124    const token = accessToken.trim();
125    if (!token) {
126      throw new ApiError("SESSION_REQUIRED", "A workspace session with an access token is required.", 401);
127    }
128    return transport<T>(path, { method: "POST", formData, signal: init?.signal, accessToken: token });
129  }
