131  /**
132   * Unauthenticated request for the /auth/* surface. Used before an access
133   * token exists (login, register) and for cookie-only refresh/logout.
134   */
135  export function publicApiRequest<T>(
136    path: string,
137    init?: { method?: string; body?: unknown },
138  ): Promise<T> {
139    return transport<T>(path, { method: init?.method, body: init?.body });
140  }
