145  /**
146   * Dictionary keys for localized hints of common API failures. The hint
147   * text itself lives in the i18n dictionaries; raw server messages are
148   * never translated here.
149   */
150  export type ErrorHintKey =
151    | "errors.hint.sessionInvalid"
152    | "errors.hint.forbidden"
153    | "errors.hint.notFound";
154  
155  export function errorHintKey(error: ApiError): ErrorHintKey | null {
156    if (error.status === 401) return "errors.hint.sessionInvalid";
157    if (error.status === 403) return "errors.hint.forbidden";
158    if (error.status === 404) return "errors.hint.notFound";
159    return null;
160  }
161  
162  export function toApiError(error: unknown, fallbackMessage: string): ApiError {
163    if (error instanceof ApiError) return error;
164    return new ApiError("REQUEST_FAILED", fallbackMessage, 0);
165  }
